                }
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header">Live Preview</div>
                    <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyles()">
                        <h5 style="@GetPreviewFontStyle()">Preview Title</h5>
                        <p style="@GetPreviewFontStyle()">
                            This is how your content will look with the current settings.
                        </p>
