                </div>

                <!-- Font Size -->
                <div class="mb-4">
                    <h5>Font Size</h5>
                    <div class="btn-group" role="group">
                        <button class="btn @(_fontSize == "Small" ? "btn-primary" : "btn-outline-primary")"
                                @onclick="() => _fontSize = \"Small\"">Small</button>
                        <button class="btn @(_fontSize == "Medium" ? "btn-primary" : "btn-outline-primary")"
                                @onclick="() => _fontSize = \"Medium\"">Medium</button>
                        <button class="btn @(_fontSize == "Large" ? "btn-primary" : "btn-outline-primary")"
                                @onclick="() => _fontSize = \"Large\"">Large</button>
                    </div>
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <h5>Language</h5>
                    <select class="form-select" @bind="_language">
                        <option value="en">English</option>
                        <option value="es">Spanish</option>
                        <option value="fr">French</option>
                        <option value="de">German</option>
                        <option value="ja">Japanese</option>
                        <option value="zh">Chinese</option>
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync">Save</button>

                @if (_showSuccess)
                {
                    <div class="alert alert-success mt-3" role="alert">Appearance settings saved!</div>
                }
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header">Live Preview</div>
                    <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyles()">
                        <h5 style="@GetPreviewFontStyle()">Preview Title</h5>
                        <p style="@GetPreviewFontStyle()">
                            This is how your content will look with the current settings.
                        </p>
                        <div class="d-flex gap-2">
                            <button class="btn btn-sm btn-primary">Button</button>
                            <button class="btn btn-sm btn-outline-secondary">Secondary</button>
                        </div>
                        <p class="mt-2 mb-0 text-muted small">
                            Theme: @_theme | Size: @_fontSize | Compact: @(_compactMode ? "Yes" : "No")
                        </p>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _loading = true;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (_theme == "Dark") classes.Add("bg-dark text-light");
        else if (_theme == "Light") classes.Add("bg-light text-dark");
        else classes.Add("bg-light text-dark");
        return string.Join(" ", classes);
    }

    private string GetPreviewStyles()
    {
        var styles = new List<string>();
        if (_compactMode) styles.Add("padding: 0.5rem;");
        else styles.Add("padding: 1.25rem;");
        return string.Join(" ", styles);
    }

    private string GetPreviewFontStyle() => _fontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.25rem;",
        _ => "font-size: 1rem;"
    };

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

