@namespace sv_f7343674fc884271a4a7547838a0e5cb.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <div class="settings-layout">
        <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />

        <div class="settings-content">
            @switch (_activeSection)
            {
                case "Profile":
                    <ProfileSection />
                    break;
                case "Notifications":
                    <NotificationsSection />
                    break;
                case "Security":
                    <SecuritySection />
                    break;
                case "Appearance":
                    <AppearanceSection />
                    break;
            }
        </div>
    </div>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

.settings-dashboard {
    max-width: 1100px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.settings-layout {
    display: flex;
    gap: 2rem;
    min-height: 600px;
}

::deep .settings-sidebar {
    min-width: 200px;
    border-right: 1px solid #dee2e6;
    padding-right: 1rem;
}

::deep .settings-sidebar .nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    color: #495057;
    background: none;
    border: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background-color 0.15s;
}

::deep .settings-sidebar .nav-link:hover {
    background-color: #f8f9fa;
}

::deep .settings-sidebar .nav-link.active {
    background-color: #0d6efd;
    color: white;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

::deep .settings-section h3 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #dee2e6;
}

